    {
        $t = $lg === 'it'
            ? ['Domanda precisa', 'luogo, periodo, confronto', 'Leggi le fonti', 'dicono davvero così?', 'Domanda successiva', 'nello stesso thread', 'La tua sintesi', 'Affermazione', 'Fonte', 'Cifra A', 'Data B', 'Cifra C', 'concordano', 'in disaccordo']
