            Q('s2', L('Con quale metodo dell’SDK ufficiale si interroga l’Agent API?', 'Which official SDK method queries the Agent API?'), ['client.responses.create', 'client.ask', 'client.search.run', 'client.answer.get'], 0, L('Con `input` ed `effort`.', 'With `input` and `effort`.')),
            Q('s3', L('Che cosa aggiunge l’API di Perplexity alle tue app?', 'What does the Perplexity API add to your apps?'), [L('Risposte aggiornate con fonti dal web', 'Up-to-date answers with web sources'), L('Immagini', 'Images'), L('Database', 'Databases'), L('Pagamenti', 'Payments')], 0, L('Ricerca integrata.', 'Built-in search.')),
